<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Espelho de ponto • <?= e($timecardEmployee['name']) ?></title><link rel="stylesheet" href="/assets/app.css"><style>.document{max-width:980px;margin:30px auto}.document-head{display:flex;justify-content:space-between;border-bottom:3px solid #173e67;padding-bottom:18px}.print-actions{display:flex;gap:10px;margin:20px 0}@media print{.print-actions,.accept-box{display:none}.document{margin:0}.panel{box-shadow:none}}</style></head><body><main class="document"><header class="document-head"><div><p class="eyebrow">ESPELHO DE PONTO ELETRÔNICO</p><h1><?= e($company['name']??'Empregador') ?></h1></div><div><strong><?= e($from) ?> a <?= e($to) ?></strong><p><?= e($timecardEmployee['name']) ?><br>Matrícula <?= e($timecardEmployee['registration']) ?></p></div></header><div class="print-actions"><button class="button primary" onclick="window.print()">Imprimir / Salvar PDF</button><a class="button ghost" href="/reports">Voltar</a></div><article class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Data</th><th>Trabalhadas</th><th>Previstas</th><th>Extras</th><th>Atrasos</th><th>Noturnas</th><th>Ocorrências</th></tr></thead><tbody><?php foreach($timecardDays as $d): ?><tr><td><?= e(date('d/m/Y',strtotime($d['work_date']))) ?></td><td><?= ReportExporter::hours($d['worked_minutes']) ?></td><td><?= ReportExporter::hours($d['expected_minutes']) ?></td><td><?= ReportExporter::hours($d['overtime_minutes']) ?></td><td><?= ReportExporter::hours($d['delay_minutes']) ?></td><td><?= ReportExporter::hours($d['night_minutes']) ?></td><td><?= e(implode(', ',json_decode($d['issues']?:'[]',true))) ?></td></tr><?php endforeach; ?></tbody></table></div></article><article class="panel accept-box"><h2>Aceite eletrônico</h2><p>Confirmo que conferi as informações apresentadas neste espelho.</p><form method="post" action="/timecard/accept"><input type="hidden" name="_token" value="<?= csrf_token() ?>"><input type="hidden" name="employee_id" value="<?= (int)$timecardEmployee['id'] ?>"><input type="hidden" name="from" value="<?= e($from) ?>"><input type="hidden" name="to" value="<?= e($to) ?>"><label>Nome completo<input name="accepted_name" required></label><button class="button primary">Registrar aceite</button></form></article></main></body></html>
